class Solution:
    def countKthPowers(self, l: int, r: int, k: int) -> int:
        if k == 1:
            return r - l + 1
        count, x = 0, 0
        while True:
            p = 1
            over = False
            for _ in range(k):
                p *= x
                if p > r:
                    over = True
                    break
            if over:
                break
            if p >= l:
                count += 1
            x += 1
        return count

