class Solution:
    def countKthPowers(self, l: int, r: int, k: int) -> int:
        def cpow(x, kk):
            p = 1
            for _ in range(kk):
                p *= x
                if p > r + 1:
                    return r + 2
            return p
        def floor_root(m):
            if m < 0:
                return -1
            e = round(m ** (1.0 / k))
            while cpow(e, k) > m:
                e -= 1
            while cpow(e + 1, k) <= m:
                e += 1
            return e
        def f(m):
            return 0 if m < 0 else floor_root(m) + 1
        return f(r) - f(l - 1)

