class Solution {
public:
    long long cpow(long long x, int k, long long cap) {
        long long p = 1;
        for (int i = 0; i < k; i++) {
            p *= x;
            if (p > cap) return cap + 1;
        }
        return p;
    }
    long long floorRoot(long long m, int k, long long cap) {
        long long e = (long long)powl((long double)m, 1.0L / k);
        while (e > 0 && cpow(e, k, cap) > m) e--;
        while (cpow(e + 1, k, cap) <= m) e++;
        return e;
    }
    int countKthPowers(int l, int r, int k) {
        auto f = [&](long long m) -> long long {
            if (m < 0) return 0;
            return floorRoot(m, k, m) + 1;
        };
        return (int)(f(r) - f((long long)l - 1));
    }
};

